document.addEventListener("DOMContentLoaded",(()=>{let e=1;const t=document.getElementById("load-more-btn"),r=document.querySelector(".listing-container"),n=Array.from(r.querySelectorAll("div.entry.resource-entry"));n.forEach(((e,t)=>{t>=6&&(e.style.display="none")}));let l=n.slice(6);t.addEventListener("click",(()=>{if(l.length>0){l.splice(0,3).forEach((e=>e.style.display=""))}else e++,fetch(`https://israeledtravelalliance.fedwebpreview.org/news-and-events?page=${e}`).then((e=>e.text())).then((e=>{const n=(new DOMParser).parseFromString(e,"text/html"),o=Array.from(n.querySelectorAll("div.entry.resource-entry"));if(0===o.length)return t.textContent="No more articles",void(t.disabled=!0);o.slice(0,3).forEach((e=>{r.appendChild(e)})),l=o.slice(3)})).catch((e=>console.error("Lazy load error:",e)))}))}));